const row = items[0].json;

const leadId = String(row['Lead ID'] || row.leadId || '').trim();
const businessName = String(row['Business Name'] || '').trim();
if (!leadId || !businessName) {
  throw new Error('Lead ID and Business Name are required');
}

const nicheId = String(row['Niche ID'] || row.nicheId || 'plumber').trim().toLowerCase();
const phone = String(row.Phone || '').replace(/\D/g, '');
const whatsappRaw = String(row.WhatsApp || phone).replace(/\D/g, '');
let whatsapp = whatsappRaw;
if (whatsapp.startsWith('0')) whatsapp = '92' + whatsapp.slice(1);
if (whatsapp.length === 10) whatsapp = '92' + whatsapp;

const slug = businessName
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .slice(0, 28);

const repoName = (`demo-${leadId}-${slug}`)
  .toLowerCase()
  .replace(/[^a-z0-9-]/g, '-')
  .replace(/--+/g, '-')
  .slice(0, 60);

const leadJson = {
  leadId,
  businessName,
  nicheId,
  category: String(row.Category || nicheId),
  phone,
  whatsapp,
  email: String(row.Email || ''),
  address: String(row.Address || ''),
  cityArea: String(row['City / Area'] || ''),
  googleMapsLink: String(row['Google Maps Link'] || ''),
  website: String(row['Website (current)'] || ''),
  rating: Number(row.Rating || 4.8),
  reviewCount: Number(row['Review Count'] || 0),
  topServices: String(row['Top services (from reviews/photos)'] || '')
    .split(/,|\|/).map(s => s.trim()).filter(Boolean),
  ownerName: String(row['Owner name (if found)'] || ''),
  yearsExperience: 5,
  workingHours: 'Open today · Reply on WhatsApp fast',
  taglineOverride: '',
  about: `${businessName} provides trusted ${nicheId} services in ${row['City / Area'] || 'your area'}.`,
  urduSupport: true
};

const leadJsonText = JSON.stringify(leadJson, null, 2);
const leadJsonBase64 = Buffer.from(leadJsonText, 'utf8').toString('base64');

return [{
  json: {
    ...row,
    leadId,
    businessName,
    nicheId,
    repoName,
    repoUrl: `https://github.com/AKStatm/${repoName}`,
    leadJsonText,
    leadJsonBase64,
    vercelProjectName: repoName.slice(0, 48)
  }
}];

