const prep = $('Prepare Lead + Repo Name').item.json;
const deployRes = items[0].json;
const deployment = (deployRes.deployments && deployRes.deployments[0]) || deployRes;
const host = deployment.url || deployment.alias?.[0] || `${prep.vercelProjectName}.vercel.app`;
const demoUrl = host.startsWith('http') ? host : `https://${host}`;

return [{
  json: {
    leadId: prep.leadId,
    demoUrl,
    repoUrl: prep.repoUrl,
    status: 'Demo Ready'
  }
}];
